CREATE TABLE public.customer_groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.customer_groups TO authenticated; GRANT ALL ON public.customer_groups TO service_role;
ALTER TABLE public.customer_groups ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin groups" ON public.customer_groups FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS customer_group_id uuid REFERENCES public.customer_groups(id), ADD COLUMN IF NOT EXISTS referral_code text UNIQUE, ADD COLUMN IF NOT EXISTS referred_by uuid REFERENCES public.profiles(id);
CREATE TABLE public.loyalty_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), points integer NOT NULL CHECK(points <> 0), reason text NOT NULL CHECK(length(reason)>0), order_id uuid REFERENCES public.orders(id), created_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.loyalty_ledger TO authenticated; GRANT ALL ON public.loyalty_ledger TO service_role;
ALTER TABLE public.loyalty_ledger ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own points or admin" ON public.loyalty_ledger FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin credits" ON public.loyalty_ledger FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') AND created_by=auth.uid());
CREATE TABLE public.admin_activity_log (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid, action text NOT NULL, entity text NOT NULL, entity_id text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_activity_log TO authenticated; GRANT ALL ON public.admin_activity_log TO service_role; GRANT USAGE,SELECT ON SEQUENCE public.admin_activity_log_id_seq TO service_role;
ALTER TABLE public.admin_activity_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin activity reads" ON public.admin_activity_log FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.record_admin_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.admin_activity_log(actor_id,action,entity,entity_id) VALUES(auth.uid(),TG_OP,TG_TABLE_NAME,CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD)->>'id' ELSE to_jsonb(NEW)->>'id' END); IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$;
CREATE TRIGGER activity_products AFTER INSERT OR UPDATE OR DELETE ON public.products FOR EACH ROW EXECUTE FUNCTION public.record_admin_activity();
CREATE TRIGGER activity_categories AFTER INSERT OR UPDATE OR DELETE ON public.categories FOR EACH ROW EXECUTE FUNCTION public.record_admin_activity();
CREATE TRIGGER activity_orders AFTER UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.record_admin_activity();
CREATE TRIGGER activity_settings AFTER INSERT OR UPDATE ON public.app_settings FOR EACH ROW EXECUTE FUNCTION public.record_admin_activity();
CREATE TRIGGER activity_roles AFTER INSERT OR UPDATE OR DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.record_admin_activity();
CREATE TABLE public.integration_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, token_hash text NOT NULL UNIQUE, scope text NOT NULL CHECK(scope IN ('catalog:read','inventory:read')), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now()+interval '90 days'), revoked_at timestamptz);
GRANT SELECT,INSERT,UPDATE ON public.integration_tokens TO authenticated; GRANT ALL ON public.integration_tokens TO service_role;
ALTER TABLE public.integration_tokens ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin integration tokens" ON public.integration_tokens FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.lead_routing_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source text NOT NULL DEFAULT '', category text NOT NULL DEFAULT '', assigned_to uuid NOT NULL REFERENCES public.profiles(id), priority integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.lead_routing_rules TO authenticated; GRANT ALL ON public.lead_routing_rules TO service_role;
ALTER TABLE public.lead_routing_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin lead routing" ON public.lead_routing_rules FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.leads ADD COLUMN IF NOT EXISTS assigned_to uuid REFERENCES public.profiles(id);
CREATE FUNCTION public.route_new_lead() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN SELECT r.assigned_to INTO NEW.assigned_to FROM public.lead_routing_rules r WHERE (r.source='' OR lower(r.source)=lower(NEW.source)) AND (r.category='' OR lower(r.category)=lower(NEW.category)) ORDER BY r.priority DESC,r.created_at LIMIT 1; RETURN NEW; END $$;
CREATE TRIGGER route_lead BEFORE INSERT ON public.leads FOR EACH ROW EXECUTE FUNCTION public.route_new_lead();
CREATE TABLE public.shipping_zones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, states text[] NOT NULL DEFAULT '{}', pincode_prefixes text[] NOT NULL DEFAULT '{}', flat_rate numeric NOT NULL DEFAULT 0 CHECK(flat_rate>=0), free_above numeric CHECK(free_above>=0), courier text NOT NULL DEFAULT '', priority integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.shipping_zones TO authenticated; GRANT ALL ON public.shipping_zones TO service_role;
ALTER TABLE public.shipping_zones ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin shipping zones" ON public.shipping_zones FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.saved_customer_carts (user_id uuid PRIMARY KEY REFERENCES public.profiles(id), items jsonb NOT NULL DEFAULT '[]', email text, recovery_consent boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), recovered_at timestamptz);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.saved_customer_carts TO authenticated; GRANT ALL ON public.saved_customer_carts TO service_role;
ALTER TABLE public.saved_customer_carts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own cart or admin read" ON public.saved_customer_carts FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Own cart insert" ON public.saved_customer_carts FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY "Own cart update" ON public.saved_customer_carts FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.cart_recovery_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), cart_updated_at timestamptz NOT NULL, stage integer NOT NULL CHECK(stage IN (1,24,72)), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent','failed')), provider_id text, error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,cart_updated_at,stage));
GRANT SELECT ON public.cart_recovery_deliveries TO authenticated; GRANT ALL ON public.cart_recovery_deliveries TO service_role;
ALTER TABLE public.cart_recovery_deliveries ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin recovery reads" ON public.cart_recovery_deliveries FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE INDEX loyalty_user ON public.loyalty_ledger(user_id,created_at);
CREATE INDEX activity_recent ON public.admin_activity_log(created_at DESC);
CREATE INDEX pending_cart_recovery ON public.saved_customer_carts(updated_at) WHERE recovery_consent=true AND recovered_at IS NULL;